-- vdb-mysql oracle regression: lookups where one key matches thousands of rows (vdb-mysql#21)
-- seed: 2
-- mode: source
-- Key q = 3 of {p}_s gets 6,000 more Source rows, and q = 4 gets 5,000, more
-- than VDB_BATCH_ROWS (4,096), so a lookup pages each key and asks for it
-- more than once (vdb-mysql-engine#9). Delta inserts, updates and deletes on
-- the same keys make every page merge Source and Delta rows.
-- source: INSERT INTO {p}_s (id, q, r) SELECT 200000 + a.d * 1000 + b.d * 100 + c.d * 10 + e.d, 3, CONCAT('m', a.d, b.d, c.d, e.d) FROM (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a, (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b, (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) c, (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) e WHERE a.d < 6;
-- source: INSERT INTO {p}_s (id, q, r) SELECT 300000 + a.d * 1000 + b.d * 100 + c.d * 10 + e.d, 4, CONCAT('n', a.d, b.d, c.d, e.d) FROM (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a, (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b, (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) c, (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) e WHERE a.d < 5;
SELECT COUNT(*), SUM(id) FROM {p}_s WHERE q = 3;
SELECT id, r FROM {p}_s WHERE q = 4 ORDER BY id;
INSERT INTO {p}_s (id, q, r) SELECT id + 500000, q, 'v' FROM {p}_s WHERE q = 3 AND id % 7 = 0;
UPDATE {p}_s SET r = 'u' WHERE q = 3 AND id % 11 = 0;
DELETE FROM {p}_s WHERE q = 4 AND id % 13 = 0;
SELECT id, r FROM {p}_s WHERE q = 3 ORDER BY id;
SELECT COUNT(*), SUM({p}_s.id), SUM({p}_a.id) FROM {p}_a JOIN {p}_s ON {p}_s.q = {p}_a.k;
SELECT {p}_a.id, {p}_s.id, {p}_s.r FROM {p}_a JOIN {p}_s ON {p}_s.q = {p}_a.k WHERE {p}_a.id < 60 AND {p}_a.k IN (3, 4) ORDER BY {p}_a.id, {p}_s.id;
SELECT /*+ BKA({p}_s) */ {p}_a.id, COUNT(*), MIN({p}_s.id), MAX({p}_s.id) FROM {p}_a JOIN {p}_s ON {p}_s.q = {p}_a.k GROUP BY {p}_a.id ORDER BY {p}_a.id;
SELECT id FROM {p}_a WHERE k IN (SELECT q FROM {p}_s WHERE r LIKE 'm%' OR r = 'u') ORDER BY id;
SELECT COUNT(*) FROM {p}_a WHERE EXISTS (SELECT 1 FROM {p}_s WHERE {p}_s.q = {p}_a.k AND {p}_s.r = 'v');
